let _toastTimer=null;function _toastShowCurrent(){const el=document.getElementById('toast');if(!el)return;const text=el.textContent.trim();if(!text){el.hidden=true;return}el.hidden=false;if(_toastTimer)clearTimeout(_toastTimer);_toastTimer=setTimeout(()=>{el.hidden=true},4000)}document.addEventListener('DOMContentLoaded',function(){const wrap=document.getElementById('toast-wrap');if(wrap){new MutationObserver(_toastShowCurrent).observe(wrap,{childList:true,subtree:true,characterData:true})}const params=new URLSearchParams(location.search);const msg=params.get('msg');if(msg){const el=document.getElementById('toast');if(el){el.textContent=msg;_toastShowCurrent()}params.delete('msg');const qs=params.toString();history.replaceState(null,'',location.pathname+(qs?'?'+qs:''))}});
